'use client'

import { useStrings, type StringsOverrides } from './strings'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Choice, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './gamestage-primitives.css'
import './choice.css'

// The host boundary. `./adapter` is a local re-export shim in this repo and the
// installed sibling file in a host application, so the one specifier resolves in
// both places.
import { useGamestageElement, type GamestageResult } from './adapter'
import { CrossGlyph, LockGlyph, StarGlyph, TickGlyph } from './glyphs'

// The cue runtime. `./feel` is a local re-export shim in this repo and the
// installed sibling file in a host application, so the one specifier resolves
// in both places. Deliberately not `element.cue`, which is the adapter's own
// path and gates on nothing: it plays while the library is muted (GSUI-84).
// `useGameFeel` is the gated one, and with no provider above it, it is a no-op.
import { useGameFeel } from './feel'

// How a label too long for its option is fitted. `./label-fit` is a local
// re-export shim in this repo and the installed sibling file in a host
// application, like `./feel` above. GSUI-281.
import {
  labelFitRootProps,
  useLabelFit,
  useLabelFitSettings,
  type LabelFitSettings,
} from './label-fit'

// Pressed while a finger is down, set from pointer events. iOS Safari does not
// apply `:active` to an element with no touch listener of its own, so without
// this a raised control never went down under a thumb (Tom, 2026-09-27). Set
// on the element directly: React does not own this attribute, so nothing
// re-renders on every touch. `.gs-pressable[data-gs-pressed='true']` in
// gamestage-primitives.css draws it, and leaves a disabled control still.
const UNPRESSABLE = ":disabled, [aria-disabled='true'], [data-gs-disabled='true'], [data-gs-locked='true']"
const pressHandlers = {
  onPointerDown: (event: React.PointerEvent<HTMLElement>) => {
    // A disabled or locked control does not move: the padlock answers instead.
    if (event.currentTarget.matches(UNPRESSABLE)) return
    event.currentTarget.setAttribute('data-gs-pressed', 'true')
  },
  onPointerUp: (event: React.PointerEvent<HTMLElement>) => event.currentTarget.removeAttribute('data-gs-pressed'),
  onPointerCancel: (event: React.PointerEvent<HTMLElement>) => event.currentTarget.removeAttribute('data-gs-pressed'),
  onPointerLeave: (event: React.PointerEvent<HTMLElement>) => event.currentTarget.removeAttribute('data-gs-pressed'),
}


/**
 * Choice: one semantic component, five presentations.
 *
 * The same question rendered as buttons, cards, a list, a wheel or an overlay is
 * the same choice. Building those as five components means five state machines,
 * five accessibility stories and five sets of bugs, and it is why this library
 * exists. Presentation is a prop.
 *
 * Choice performs nothing. It does not fetch, does not persist, does not decide
 * whether an answer is right, and does not know who the player is. It reports
 * what the player did and renders what it is told. The host settles the outcome
 * and passes it back, either as the `result` prop or, when the host has wired
 * up an adapter and given this choice an `elementId`, through the adapter's
 * `subscribeForResults`. Both routes end at the same render: the prop is the
 * direct one, the adapter is the one that survives the host being a server.
 *
 * Choice never guesses an outcome for itself, because deciding which option was
 * right is the host's job and doing it here would be the library settling the
 * game. It will render the host's guess: pass `optimistic` and what it returns
 * is on screen in the same tick as the tap, then confirmed or corrected when
 * the host's own answer arrives. Without it the sub-100ms feedback is the
 * committed state, which is synchronous and local. GSUI-127.
 */

export type ChoiceState = 'idle' | 'selected' | 'committed' | 'correct' | 'wrong' | 'rewarded'

export type ChoicePresentation = 'buttons' | 'cards' | 'list' | 'wheel' | 'overlay'

export interface ChoiceOption {
  id: string
  label: string
  /**
   * What the label names. `person` lets a name that does not fit be shortened
   * to "J. Verhoeven" under the `nameFormat` setting. Nothing is shortened
   * without it: a club or a country is never guessed to be a name. GSUI-281.
   */
  kind?: 'person'
  /**
   * A person's given and family names, for the two-line name a `person` option
   * draws: the given name small and light above, the family name bold below.
   * Without them the label is split at its first space ("Ruud / van
   * Nistelrooy"); one word stays one line. Tom, 2026-09-28.
   */
  given?: string
  family?: string
  /**
   * The letter in the tile's corner: A, B, C, D in a quiz grid (specimen 1h).
   * Drawn on a raised square in the display face, and when the option settles
   * the tick or the cross takes its place, so the corner is where a player
   * looks for the answer as well as the key. Optional: without it the mark
   * lands in the opposite corner as before.
   */
  key?: string
  /** Optional supporting line. Never carries meaning that the label does not. */
  detail?: string
  media?: React.ReactNode
  /**
   * What this option won, already formatted and signed: `'+250'`, `'x2'`, `'a
   * free spin'`. Rendered as a badge floating clear of the corner, and only
   * when the option settles `rewarded`; at every other point in the round there
   * is nothing to have won yet. Host-formatted rather than a number, because
   * the sign, the separator and the unit are all the game's to decide.
   */
  reward?: string
  /** Not available at all. Flat, no padlock. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
}

export interface ChoiceResult {
  /** Which options settled which way. Absent ids are left unsettled. */
  [optionId: string]: 'correct' | 'wrong' | 'rewarded'
}

/**
 * The props Choice hands its commit control. Spread them onto whatever the
 * host renders and the control is Choice's: it commits the current selection,
 * it is a real `button` so the keyboard already works, it carries the part
 * attributes a theme and a test read, and it says "Lock it in" unless
 * `commitLabel` says otherwise.
 *
 * Anything written after the spread wins, which is how a host changes the word
 * or takes the press for its own next step:
 *
 * ```tsx
 * commit={(control, round) => (
 *   <Button {...control} onClick={round.settled ? next : control.onClick}>
 *     {round.settled ? 'Next question' : 'Lock it in'}
 *   </Button>
 * )}
 * ```
 */
export interface ChoiceCommitControl {
  type: 'button'
  className: string
  /** Locks the current selection in. A no-op when there is nothing to lock. */
  onClick: () => void
  /** Nothing is selected, or the round is already over. */
  disabled: boolean
  children: React.ReactNode
  'data-gs-scope': 'choice'
  'data-gs-part': 'commit'
  'data-gs-animates': 'motion'
}

/**
 * Where the round has got to, so a host's control can say the right word. A
 * handful of plain facts rather than one phase name: a host that only cares
 * about one of them reads one of them.
 */
export interface ChoiceRound {
  /** The option ids picked but not yet locked in. */
  selected: string[]
  /** Something is picked and the round is still open, so a commit would do something. */
  ready: boolean
  /** The player has locked an answer in. */
  committed: boolean
  /** The host has settled at least one option. */
  settled: boolean
  /** The host closed the round. */
  closed: boolean
  /**
   * Every option the player had picked has since left `options`, so the round
   * is taking answers again and the player has none. GSUI-151.
   */
  stale: boolean
}

/**
 * State colours: custom properties on the option, each defaulting to a theme
 * token, so a theme or a game restyles a state without restating the rule:
 * `--gs-choice-selected-fill`, `-selected-ink`, `-selected-edge`,
 * `-correct-fill`, `-correct-ink`, `-wrong-fill`, `-wrong-ink`, `-wrong-edge`,
 * `-disabled-fill` and `-disabled-ink`. choice.css lists each default. Selected
 * never shares a colour with the primary action or with correct.
 *
 * The label settings: `labelFit`, `maxLines`, `shrinkFloor`, `nameFormat`,
 * `groupFit` and `fitGroup`. Defaults are wrap, 2, 0.85, full, uniform and no
 * shared group; a `LabelFitProvider` above sets them app-wide. See
 * `label-fit.tsx`. GSUI-281.
 */
/**
 * A person's name on two lines. The option's own given and family names when
 * it carries them, otherwise the label split at its first space. One word, or
 * nothing to split, stays one line; the family line always has words in it,
 * falling back to the label, so a name is never drawn blank.
 */
export function twoLineName(option: Pick<ChoiceOption, 'kind' | 'label' | 'given' | 'family'>): {
  given: string
  family: string
} | null {
  const given = option.given?.trim() ?? ''
  const family = option.family?.trim() ?? ''
  if (family) return { given, family }
  if (option.kind !== 'person') return null
  const label = option.label.trim()
  const space = label.indexOf(' ')
  if (space < 0) return { given: '', family: label || option.label }
  return { given: label.slice(0, space), family: label.slice(space + 1).trim() || label }
}

export interface ChoiceProps extends LabelFitSettings {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides
  /**
   * How a `person` option draws its name. `two` (the default) puts the given
   * name small and light above the family name, bold, both centred; `one`
   * draws the label on one run as before. Tom, 2026-09-28.
   */
  nameLines?: 'two' | 'one'

  options: ChoiceOption[]
  presentation?: ChoicePresentation
  /** The question. Rendered above the options and as the group's name. */
  label: string
  /**
   * The line under the question: a rule, a stake, how long is left. Never
   * carries meaning the question does not, exactly as an option's `detail`
   * does not carry meaning its label does not.
   */
  detail?: React.ReactNode
  /** More than one pick allowed. */
  multiple?: boolean
  /**
   * Commit as soon as the player picks, with no separate confirm step. Use it
   * for fast rounds; leave it off when a player should be able to change their
   * mind, because an accidental tap that cannot be undone reads as a bug.
   */
  commitOnSelect?: boolean
  /**
   * The word on the commit control. Defaults to "Lock it in". It is the
   * control's accessible name as well as the words on it, so it says what
   * pressing it does rather than naming the game.
   */
  commitLabel?: React.ReactNode
  /**
   * The host renders the commit control itself.
   *
   * Given this, Choice draws no commit control of its own and calls this
   * instead, at every point in the round: before a pick, after one, once the
   * answer is locked in and once the host has settled it. That is the whole
   * reason it exists. Choice's own control appears on a selection and unmounts
   * on settlement, so it can never be the one control a game screen keeps in
   * one place while its word changes from Lock it in to Next question, which
   * is what `docs/mobile-game-frame.md` asks for.
   *
   * The first argument is the control: spread it and the press still commits,
   * the keyboard still works, and the part attributes are still there. The
   * second says where the round has got to, so the host can choose the word.
   *
   * A host that takes the control owns saying what it does at every point in
   * the round, including the points where there is nothing to commit. A
   * control that sits padlocked and wordless for half a round is worse than
   * the one this replaces.
   */
  commit?: (control: ChoiceCommitControl, round: ChoiceRound) => React.ReactNode
  /** Settled outcomes from the host. Presence of this switches to result states. */
  result?: ChoiceResult
  /**
   * What to put on screen the instant the player commits, before the host has
   * answered. Only useful with `elementId`, because it is the adapter that
   * reconciles it: what this returns renders immediately, and when the host
   * settles, an answer that agrees is a confirmation and one that disagrees
   * is a correction, which `onSettled` reports as a second event.
   *
   * This is the host's guess and not Choice's. A quiz whose answer key is
   * already on the device returns the real outcome; a game that cannot know
   * yet leaves this off and the player waits, which is right for a round
   * everyone expects to wait for and wrong for a quiz. GSUI-127.
   *
   * Nothing is counted from a guess: analytics wait for the host.
   */
  optimistic?: (optionIds: string[]) => GamestageResult[]
  /**
   * Names this choice to the host adapter. With it, a select and a commit reach
   * `track` and `submit`, and settled outcomes arrive through
   * `subscribeForResults` without the host re-rendering Choice with a `result`.
   * Without it Choice behaves exactly as it did before the adapter existed:
   * every callback still fires and the host still drives `result`.
   */
  elementId?: string
  /** Locks everything without settling, for a closed round. */
  closed?: boolean

  onSelected?: (optionId: string) => void
  onCommitted?: (optionIds: string[]) => void
  /**
   * Fired once per settled option when `result` arrives.
   *
   * This said "Cues sound and haptics", which it does not do: no component in
   * the library fires a cue, which is GSUI-92. A host that wants sound or a
   * haptic on a settlement calls the feel runtime from this callback itself.
   */
  onSettled?: (optionId: string, state: 'correct' | 'wrong' | 'rewarded') => void
  /**
   * Options the player had picked are no longer in `options`, so the answer
   * they gave cannot be shown and cannot be settled. Fired with the ids that
   * went, once per change, and the host decides what to say about it: only the
   * host knows whether the bracket re-drew, the question was replaced or the
   * feed corrected itself. GSUI-151.
   */
  onSelectionLost?: (optionIds: string[]) => void
}

/** Glyphs, because colour alone is not an answer. Committed carries the
 * padlock: the drawing (1e, 1h, 2b) locks the chosen tile with one, so a fill
 * is never the only thing that says the answer can no longer change. */
const GLYPH: Record<string, React.ReactNode> = {
  committed: <LockGlyph />,
  correct: <TickGlyph />,
  wrong: <CrossGlyph />,
  rewarded: <StarGlyph filled />,
}

/** What the commit control says when nobody has said otherwise. */

export function Choice(props: ChoiceProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const DEFAULT_COMMIT_LABEL = copy['choice.commitLabel']
  const STATE_LABEL: Record<string, string> = {
    selected: copy['choice.selected'],
    committed: copy['choice.lockedIn'],
    correct: copy['choice.correct'],
    wrong: copy['choice.wrong'],
    rewarded: copy['choice.rewarded'],
  }
  const {
    options,
    presentation = 'buttons',
    label,
    detail,
    multiple = false,
    commitOnSelect = false,
    commitLabel = DEFAULT_COMMIT_LABEL,
    commit: renderCommit,
    result,
    optimistic,
    elementId,
    closed = false,
    onSelected,
    onCommitted,
    onSettled,
    onSelectionLost,
    labelFit,
    maxLines,
    minLines,
    shrinkFloor,
    nameFormat,
    groupFit,
    fitGroup,
    nameLines = 'two',
  } = componentProps

  // The labels are fitted once the group has laid out, and again only on a
  // real resize or font load: picking, locking and settling are not inputs
  // here, so the board never moves under a thumb. GSUI-281.
  const rootRef = React.useRef<HTMLDivElement>(null)
  const fitResolved = useLabelFitSettings({ labelFit, maxLines, minLines, shrinkFloor, nameFormat, groupFit, fitGroup })
  // Every option is given room for `maxLines` unless the author says fewer, so
  // a board of one-line and two-line names is one height throughout. Tom,
  // 2026-09-27: "make all buttons 2 line height".
  const fitSettings = { ...fitResolved, minLines: fitResolved.minLines ?? fitResolved.maxLines }
  const fitItems = React.useMemo(
    () => options.map((o) => ({ id: o.id, label: o.label, person: o.kind === 'person' })),
    [options],
  )
  const fit = useLabelFit(rootRef, fitItems, fitSettings)
  const fitRoot = labelFitRootProps(fitSettings, fit)

  const [selected, setSelected] = React.useState<string[]>([])
  const [committed, setCommitted] = React.useState(false)
  // The last outcome reported for each option, not merely which options have
  // been reported. A `Set` of ids said "this option has settled" and could not
  // say "it settled the other way just now", so a host re-settling a question
  // (a goal given and then disallowed) rendered the cross and fired nothing:
  // no `onSettled`, no `report`, no cue, no analytics. Keyed on the settlement
  // rather than the option, a second settlement with a different outcome is a
  // new event and one with the same outcome is still the same event, which is
  // what the guard was for. GSUI-150.
  const settledAlready = React.useRef(new Map<string, 'correct' | 'wrong' | 'rewarded'>())

  // And the same book for analytics, kept separately because the two answer
  // different questions. What the player saw includes the guess `optimistic`
  // put on screen; what the host settled does not. Counting the guess would
  // report a pass rate the host never agreed to, so `report` waits. GSUI-127.
  const reportedAlready = React.useRef(new Map<string, 'correct' | 'wrong' | 'rewarded'>())

  // Called unconditionally, with or without an element id, because that is what
  // the rules of hooks require. Given none it subscribes to nothing and tells
  // the host nothing.
  const element = useGamestageElement(elementId)

  // What the adapter has settled, in the shape this component renders.
  const fromHost = React.useMemo<ChoiceResult | undefined>(() => {
    if (element.results.length === 0) return undefined
    const settled: ChoiceResult = {}
    for (const one of element.results) settled[one.optionId] = one.state
    return settled
  }, [element.results])

  // An explicit prop wins. A host passing `result` is answering directly, and
  // two sources of truth for one question is how a round ends up rendering the
  // previous round's answer.
  const outcome = result ?? fromHost

  const { report, settlement } = element
  const { cue } = useGameFeel()
  // A guess the host has not answered yet. The player gets the render and the
  // cue, because they tapped and they are owed feedback; analytics do not.
  const unconfirmed = settlement === 'optimistic'

  // The host settles. Report each settlement once, so a re-render does not
  // replay the sound, and report a settlement that changed, because a host
  // changing its mind is something that happened to the player.
  React.useEffect(() => {
    if (!outcome) return
    for (const [id, state] of Object.entries(outcome)) {
      if (!unconfirmed && reportedAlready.current.get(id) !== state) {
        reportedAlready.current.set(id, state)
        report(id, state)
      }
      if (settledAlready.current.get(id) === state) continue
      settledAlready.current.set(id, state)
      onSettled?.(id, state)
      // The design's feedback sheet, specimen 4a and 4b: "Correct · motion.pop
      // 400ms, overshoot 1.12 · sfx.correct (bright, short) · haptic.success"
      // and "Wrong · motion.shake 400ms, ±6px, 3 cycles · sfx.wrong (low, dull,
      // never harsh) · haptic.error · reduced-motion: dashed only". The shake
      // and the dashed stroke are choice.css; this is what it sounds like.
      //
      // `rewarded` fires nothing yet: the design settles a reward on the reward
      // component (specimen 3f, sfx.reveal then sfx.reward), and firing a
      // second cue from here would be the same state change twice.
      if (state === 'correct') {
        cue('correct', 'sfx')
        cue('success', 'haptic')
      } else if (state === 'wrong') {
        cue('wrong', 'sfx')
        cue('error', 'haptic')
      }
    }
  }, [outcome, unconfirmed, onSettled, report, cue])

  // The host's word for a round that is over: the `closed` prop, or the adapter
  // reporting this element locked or closed. Kept apart from `locked` below
  // because a round the player closed by answering is a different fact, and
  // `data-gs-closed` is only ever the host's.
  const closedByHost = closed || element.state === 'locked' || element.state === 'closed'

  // A settled round locks the board too. An *empty* result map is not a settled
  // round: it is the value a host holds before anything has settled, and
  // `useState<ChoiceResult>({})` is how a React host holds a map it fills over
  // time. `!!outcome` was true for `{}`, so passing the obvious initial value
  // decided the round was over on first render: every option aria-disabled,
  // `pick` returning before it fired a callback, and a board that did nothing
  // when a player clicked it. Found by building a game against the library and
  // clicking a card; automation only reported "element is not enabled", which
  // reads as a tooling quirk rather than a dead component.
  const roundSettled = !!outcome && Object.keys(outcome).length > 0

  // A selection can outlive the option it names. A bracket re-draws when the
  // tie feeding it resolves, and `options` arrives holding two real teams where
  // it held "Winner of match 3", which is the id the player committed to.
  //
  // Derived at render rather than repaired in an effect: an effect clears the
  // selection one paint late, and that paint is the bug, a board where every
  // option is `aria-disabled` and nothing says why. GSUI-151.
  const lost = selected.filter((id) => !options.some((option) => option.id === id))
  // Some of the picks surviving is not the same event. A multiple choice that
  // lost one of three options still has an answer, so the round stands and only
  // the option that went is dropped. Stale is the whole answer disappearing.
  const live = selected.filter((id) => options.some((option) => option.id === id))
  const stale = selected.length > 0 && live.length === 0

  // A round nobody can answer is worse than one nobody has answered, so a
  // stale commit does not lock the board. The host has been told; the player
  // gets to pick from what is actually there.
  const locked = (committed && !stale) || closedByHost || roundSettled

  // Once per change, and never for a round whose options never moved. The key
  // is the ids rather than the array, which is new on every render.
  const lostKey = lost.join('\u0000')
  React.useEffect(() => {
    if (lostKey === '') return
    onSelectionLost?.(lostKey.split('\u0000'))
    // `onSelectionLost` is deliberately out of the dependency list: a host
    // handing a fresh closure on every render would otherwise be told the same
    // options went, over and over.
  }, [lostKey])

  // A commit would do something: the player has picked, and the round is still
  // taking answers. It is the condition the built-in control appeared on, named
  // so the host's control can be told the same fact rather than working it out
  // from three props.
  const readyToCommit = !locked && live.length > 0

  function pick(option: ChoiceOption) {
    if (locked || option.disabled || option.locked) return
    const next = multiple
      ? live.includes(option.id)
        ? live.filter((id) => id !== option.id)
        : [...live, option.id]
      : [option.id]
    setSelected(next)
    // The answer that went with the old options went with them. Answering again
    // is answering, not re-answering, so the commit the player no longer has
    // does not lock the board a second time.
    if (stale) setCommitted(false)
    onSelected?.(option.id)
    element.select(option.id)
    if (commitOnSelect && !multiple) {
      // One state change, one sound (the design's cue rules, specimen 4h:
      // "one sound per state change · never on hover"). Committing on select is
      // a single act, so it gets the commit cue and not a select before it.
      commit(next)
      return
    }
    // Specimen 4g draws the same act on a carousel as "sfx.select on settle ·
    // haptic.light", and the catalogue's own words for the two are "soft click"
    // and "tap, select, collect". Picking an option is a selection, not a
    // generic button press, so it is `select` rather than `press`.
    cue('select', 'sfx')
    cue('light', 'haptic')
  }

  function commit(optionIds: string[]) {
    setCommitted(true)
    onCommitted?.(optionIds)
    // Locking an answer in: the catalogue's `commit` is "lock, weighted" and
    // haptic.medium is "commit, streak, GO".
    cue('commit', 'sfx')
    cue('medium', 'haptic')
    // The guess is the host's, handed forward as well as rendered, so the host
    // can tell whether its own answer confirms what the player already saw or
    // corrects it. Without the prop this is the call it always was.
    element.commit(optionIds, optimistic ? { optimistic: optimistic(optionIds) } : undefined)
  }

  /**
   * What the player did with this option. Independent of how it turned out: an
   * option the player committed keeps `committed` after the round settles,
   * because committed means locked in and no longer reversible, which a settled
   * option is. Reading the two as one ladder is what used to drop the player's
   * own answer off the results screen.
   */
  function pickOf(option: ChoiceOption): 'selected' | 'committed' | undefined {
    if (!selected.includes(option.id)) return undefined
    return locked ? 'committed' : 'selected'
  }

  /** How it turned out. The host's fact, not the component's. */
  function settledOf(option: ChoiceOption): 'correct' | 'wrong' | 'rewarded' | undefined {
    return outcome?.[option.id]
  }

  /** The one word the accessible name uses: the outcome if there is one, else the pick. */
  function stateOf(option: ChoiceOption): ChoiceState {
    return settledOf(option) ?? pickOf(option) ?? 'idle'
  }

  // The question, on the screen.
  //
  // `label` was the group's accessible name and nothing else, so the one thing
  // a choice exists to ask was announced to a screen reader and invisible to
  // everyone else: a sighted player saw the options and no question. That is
  // backwards from the usual failure, where the visible text exists and the
  // name is missing.
  //
  // It is `aria-labelledby` now rather than `aria-label`, so the name comes
  // from the words on the screen instead of a second copy of them. A host that
  // renders its own heading and passes the same string no longer has it read
  // twice.
  const labelId = React.useId()

  return (
    <div
      ref={rootRef}
      className="gs-choice"
      data-gs-component="choice"
      data-gs-presentation={presentation}
      data-gs-label-fit={fitRoot['data-gs-label-fit']}
      data-gs-label-lines={fitRoot['data-gs-label-lines']}
      style={fitRoot.style}
      data-gs-closed={closedByHost ? 'true' : undefined}
      data-gs-stale={stale ? 'true' : undefined}
      role={multiple ? 'group' : 'radiogroup'}
      aria-labelledby={labelId}
    >
      <p className="gs-choice__question" id={labelId} data-gs-scope="choice" data-gs-part="label">
        {label}
      </p>
      {detail ? (
        <p className="gs-choice__subtitle" data-gs-scope="choice" data-gs-part="detail">
          {detail}
        </p>
      ) : null}
      {options.map((option) => {
        const playerPick = pickOf(option)
        const settled = settledOf(option)
        const state = stateOf(option)
        const isResult = !!settled
        const unavailable = option.disabled || option.locked || (locked && !isResult)
        // Flat is for a control with nothing of its own to show. A settled
        // option, the option the player picked and an option carrying its own
        // padlock all draw something a player reads; every other option in a
        // round that is over is simply not available, and goes flat. That is
        // how the design dims the answers nobody picked once the round is over
        // (BDS-012, specimen 1h), and it is the attribute a host or a test
        // reads to see a closed round on the options themselves.
        const unpicked = !option.disabled && locked && !isResult && !playerPick && !option.locked
        const flat = option.disabled || unpicked

        // The accessible name carries the state, because a screen reader user
        // gets no fill, no stroke and no glyph. The reward badge goes in here
        // too: it is the only place the amount appears that is not a drawing,
        // and a player who cannot see the badge has otherwise been told they
        // were rewarded without being told what with.
        const stateWord = STATE_LABEL[state]
        const words = [option.label]
        if (stateWord) words.push(stateWord)
        if (state === 'rewarded' && option.reward) words.push(option.reward)
        const ariaLabel = words.join(', ')

        // The mark: a padlock for a locked or committed option, the outcome's
        // glyph once settled. A settled option with a key shows the mark in
        // the key's square rather than the opposite corner.
        const mark = option.locked ? <LockGlyph /> : GLYPH[state]
        const markInKey = Boolean(option.key) && isResult

        // What is drawn, which may be a shortened name. The accessible name
        // above is built from `option.label`, so it is always the full one.
        const plan = fit.plans.get(option.id)
        const name = nameLines === 'two' ? twoLineName(option) : null
        const drawn = name ? (
          <>
            {name.given ? <span className="gs-choice__given">{name.given}</span> : null}
            <span className="gs-choice__family">{name.family}</span>
          </>
        ) : (
          <span className="gs-choice__text">{plan?.text ?? option.label}</span>
        )
        const labelStyle =
          plan && fitSettings.groupFit === 'each'
            ? ({ ['--gs-label-scale' as string]: plan.scale } as React.CSSProperties)
            : undefined

        return (
          <button
            key={option.id}
            type="button"
            className="gs-choice__option gs-action-type gs-pressable"
            {...pressHandlers}
            data-gs-choice={option.id}
            data-gs-selected={playerPick === 'selected' ? 'true' : undefined}
            data-gs-committed={playerPick === 'committed' ? 'true' : undefined}
            data-gs-state={settled}
            data-gs-disabled={flat ? 'true' : undefined}
            data-gs-unpicked={unpicked ? 'true' : undefined}
            data-gs-locked={option.locked ? 'true' : undefined}
            data-gs-label-name={plan?.name}
            // The option moves on press and on the wrong-answer shake, so it is
            // motion. Its fill, glyph and glow are emphasis and survive reduced
            // motion, which is how a player who cannot see movement still gets
            // the answer.
            data-gs-animates="motion"
            role={multiple ? 'checkbox' : 'radio'}
            // The pick, not the outcome. A radio that reads unchecked on the
            // results screen tells a screen reader user the player answered
            // nothing.
            aria-checked={!!playerPick}
            aria-label={ariaLabel}
            aria-disabled={unavailable || undefined}
            disabled={option.disabled}
            onClick={() => pick(option)}
          >
            {option.key ? (
              <span className="gs-choice__key" aria-hidden="true">
                {markInKey ? (
                  <span className="gs-choice__glyph" data-gs-animates="emphasis">{mark}</span>
                ) : (
                  option.key
                )}
              </span>
            ) : null}
            {option.media ? <span className="gs-choice__media">{option.media}</span> : null}
            <span
              className="gs-choice__label"
              ref={name ? undefined : fit.labelRef(option.id)}
              style={name ? undefined : labelStyle}
              data-gs-names={name ? (name.given ? 'two' : 'one') : undefined}
            >
              {drawn}
            </span>
            {/* A card keeps a line for its detail whether or not it has one,
                so an option that gains a line mid-play (a wrong guess saying
                why) does not grow and move the board. Tom, 2026-09-27. */}
            {option.detail ? (
              <span className="gs-choice__detail">{option.detail}</span>
            ) : presentation === 'cards' ? (
              <span className="gs-choice__detail" data-gs-empty="true" aria-hidden="true">{'\u00a0'}</span>
            ) : null}
            {mark && !markInKey ? (
              option.locked ? (
                <span className="gs-choice__glyph" aria-hidden="true">{mark}</span>
              ) : (
                <span className="gs-choice__glyph" data-gs-animates="emphasis" aria-hidden="true">
                  {mark}
                </span>
              )
            ) : null}
            {/* The amount won, floating clear of the corner rather than sitting
                inside the control (BDS-012, specimen 1e). Hidden, because the
                accessible name above already carries it; announcing it here as
                well reads the amount twice. `delta` is the part vocabulary's
                word for a signed change, which is what this is. */}
            {state === 'rewarded' && option.reward ? (
              <span
                className="gs-choice__reward"
                data-gs-scope="choice" data-gs-part="delta"
                data-gs-animates="emphasis"
                aria-hidden="true"
              >
                {option.reward}
              </span>
            ) : null}
          </button>
        )
      })}

      {renderCommit
        ? renderCommit(
            {
              type: 'button',
              // Placement only. The host's control keeps its own face, and
              // `gs-choice__commit` is what puts it across the grid under the
              // options rather than beside the last one.
              className: 'gs-choice__commit',
              onClick: () => {
                if (!readyToCommit) return
                commit(live)
              },
              disabled: !readyToCommit,
              children: commitLabel,
              'data-gs-scope': 'choice',
              'data-gs-part': 'commit',
              'data-gs-animates': 'motion',
            },
            {
              selected: live,
              ready: readyToCommit,
              committed: committed && !stale,
              settled: roundSettled,
              closed: closedByHost,
              stale,
            },
          )
        : !commitOnSelect && readyToCommit ? (
            <button
              type="button"
              className="gs-choice__commit gs-choice__commit--default gs-action-type gs-pressable"
              {...pressHandlers}
              data-gs-scope="choice" data-gs-part="commit"
              data-gs-animates="motion"
              onClick={() => commit(live)}
            >
              {commitLabel}
            </button>
          ) : null}
    </div>
  )
}

/* Choice. Every value comes from a token; nothing here is a literal colour.

   Three specimens draw the option and design/twins/1e, 1h and 2b measure ours
   against them: 1e is one control in every state in the base theme, 1h is the
   2x2 quiz grid the `buttons` presentation is for, and 2b is the same states in
   arcade. The paint of each state comes from 1e and 2b; the geometry of the
   grid tile comes from 1h. */

.gs-choice {
  display: grid;
  gap: var(--gs-space-3);
}

/* The two-column presentations read their own width, not the viewport's. A
   choice is as wide as the layer that holds it, and on a 320px phone the
   interaction layer hands it about 288 after the stage's insets, so a rule
   written against the viewport measures the wrong box.

   Only these two ask it, because only these two are two columns wide.
   `container-type: inline-size` stops an element contributing to an
   intrinsic width, which is how the HUD came to measure zero in a layer that
   hugged its contents (GSUI-218), so it goes on the presentations whose width
   is always given to them: the buttons grid in flow, and the overlay, which
   takes its width from its own insets. */
.gs-choice[data-gs-presentation='buttons'],
.gs-choice[data-gs-presentation='overlay'] {
  container-type: inline-size;
}

/* Below 378px the grid is one column, because that is the width two columns
   need. Measured on the lab: "Verstappen" at the action size is a 149px run,
   the option's inset and outline add 34, so a column has to be 183 wide and
   two of them with the gap between are 378. A 320px phone's interaction layer
   gives the choice about 288 and a 390px phone about 358, so below this the
   second column was breaking the word in half and drawing "Verstapp/en". The
   label stayed inside its option, which is all the boundary stage measures,
   and it was not an answer anybody should have to reassemble.

   One column rather than a smaller type. The drawing sets the tile's type at
   16px where ours takes the 18px action size, and at 16px the word fits two
   columns on a 390px phone; there is no 16px step in the action role to reach
   for, and a component raises a token request rather than inventing one. Until
   that token exists the presentation gives way instead, which is what the
   drawing would rather have than half a driver's name.

   The grid is on the root and an element cannot query itself, so the options
   carry the rule and span both tracks. */
@container (max-width: 377px) {
  .gs-choice[data-gs-presentation='buttons'] .gs-choice__option,
  .gs-choice[data-gs-presentation='overlay'] .gs-choice__option {
    grid-column: 1 / -1;
  }
}

/* minmax(0, 1fr), not 1fr. A grid track's default minimum is its content, so
   a two-column grid of 1fr refuses to go narrower than the longest option and
   the whole grid grows past the box that holds it. In the overlay
   presentation, which is absolutely positioned over the host's scene and has
   no room to grow into, that put the question 24px and "Russell" 5px outside
   the component at 390. The option truncates and wraps below; this is what
   lets it. */
.gs-choice[data-gs-presentation='buttons'] { grid-template-columns: repeat(2, minmax(0, 1fr)); }
/* A wrapping row, not an auto-fit grid: the question spans every track, so
   none collapsed, and four cards sat in seven 142px tracks cut to "Verst...".
   192px holds "Verstappen" (183px, measured below). */
.gs-choice[data-gs-presentation='cards'] {
  display: flex;
  flex-wrap: wrap;
}
.gs-choice[data-gs-presentation='cards'] > * { flex: 1 1 100%; }
.gs-choice[data-gs-presentation='cards'] > .gs-choice__option {
  flex: 1 1 calc(var(--gs-size-icon-hero) * 3);
}
/* minmax(0, 1fr) in the one-column presentations too. `1fr` is
   `minmax(auto, 1fr)`, whose minimum is the track's content, and the label no
   longer breaks inside a word (see .gs-choice__label), so its min-content is a
   whole word rather than one character. Without this a name longer than the
   phone is wide would widen the track and push the option out of the
   component, which is the fault this grid was given minmax for in the first
   place. */
.gs-choice[data-gs-presentation='list']    { grid-template-columns: minmax(0, 1fr); }
.gs-choice[data-gs-presentation='wheel']   { grid-template-columns: minmax(0, 1fr); place-items: center; }
/* An overlay sits over the host's scene, so it is absolutely positioned and
   needs a positioned ancestor. Give it one, or it resolves against the viewport
   and lands across the whole page, over anything else on it. The library cannot
   create that ancestor: the scene is the host's. */
.gs-choice[data-gs-presentation='overlay'] {
  position: absolute; inset: auto 0 0 0;
  padding: var(--gs-space-4);
  background: var(--gs-color-scrim);
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

/* The question. It spans the grid because it is about the set rather than one
   option. The part is `label`, the vocabulary's word for what a thing is
   called; the class is its own so it does not collide with an option's label. */
.gs-choice__question {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--gs-color-ink);
  /* `title`, not `label`. A question is the heading of the set, and label is
     the 13px uppercase caption that sits under a stat's number. */
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: 1.2;
  text-wrap: balance;
}

/* The line under the question. `caption` is the drawing's own role for it: the
   small explanatory line under a control or a card, its most used text style. */
.gs-choice__subtitle {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--gs-color-ink-secondary);
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
}

.gs-choice__option {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: var(--gs-space-1);
  position: relative;

  /* A grid item's automatic minimum is its content, which is how an option
     widens its own column and pushes the grid past the component. What the
     label does with the room it is left is on .gs-choice__label below: it
     wraps between words and is cut with an ellipsis only where one word
     cannot fit at all. */
  min-inline-size: 0;

  /* 48px is the smallest target a thumb reliably hits. */
  min-height: var(--gs-size-touch-min);
  /* The padding gives back whatever a state adds to the border, so picking an
     option never changes its size. In base and stadium the selected stroke is
     3px against a 1px control stroke, and a picked card grew by 4px and pushed
     its row down under the player's thumb (GSUI-281, found in the Wage Bill
     test game). --gs-choice-grow is the difference, set by the states below;
     it is negative where a theme draws the selected stroke thinner. */
  --gs-choice-pad-block: var(--gs-space-3);
  --gs-choice-pad-inline: var(--gs-space-4);
  padding: calc(var(--gs-choice-pad-block) - var(--gs-choice-grow, 0px))
           calc(var(--gs-choice-pad-inline) - var(--gs-choice-grow, 0px));

  text-align: left;

  color: var(--gs-color-ink);
  /* surface, not surfaceRaised: every drawn idle tile sits on the surface
     colour (1e, 1h, 2b) and lifts to raised only under the pointer. */
  background: var(--gs-color-surface);
  /* The outline every control carries, in edge: 2b rings every tile at 3px. */
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-raised);
  cursor: pointer;

  /* Only the movement is timed here. Fill and glyph transitions live on the
     emphasis elements so they survive reduced motion. */
  transition: transform var(--gs-motion-press) var(--gs-motion-ease-press),
              box-shadow var(--gs-motion-press) var(--gs-motion-ease-press);
}

/* The quiz grid tile, specimen 1h: 18px corners, the drawing's 14px inset, the
   key in the top corner and the answer at the foot. The drawing fixes the tile
   at 104px; no size token is that tall, so ours stands the key and the label
   apart and takes its height from them until a size.tile token exists. */
.gs-choice[data-gs-presentation='buttons'] .gs-choice__option {
  justify-content: space-between;
  gap: var(--gs-space-2);
  --gs-choice-pad-block: var(--gs-space-inset);
  --gs-choice-pad-inline: var(--gs-space-inset);
  border-radius: var(--gs-radius-lg);
}

/* The option's picture. choice.tsx has always rendered this element and this
   file never styled it, so `media` was a prop with nothing behind it and
   whatever a host passed landed raw. A square well, so a grid of cards keeps
   one baseline whatever they hold; reward.css and onboarding.css style theirs
   the same way. */
.gs-choice__media {
  display: flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-hero);
  block-size: var(--gs-size-icon-hero);
  flex: none;
  overflow: hidden;
  border-radius: var(--gs-radius-sm);
}

/* Real media fills the well and crops rather than stretching. Without this an
   image keeps its own dimensions and the card grows to hold it. */
.gs-choice__media > img,
.gs-choice__media > picture,
.gs-choice__media > video {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
  display: block;
}

.gs-choice__option:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* 1e's "hover / raised": the tile lifts to the raised colour and the high edge.
   Only where a pointer can hover, and never over a selection: a phone keeps
   :hover on the last tile tapped, and this rule outranks the selected one, so
   on an iPhone the chosen tile went back to the raised face and looked like
   every other. Tom, 2026-09-27. */
@media (hover: hover) {
  .gs-choice__option:hover:not([aria-disabled='true']):not([data-gs-selected='true']):not([data-gs-committed='true']) {
    background: var(--gs-color-surface-raised);
    border-color: var(--gs-color-edge-high);
  }
}

/* Pressable controls never fade or darken. A tile has no offset base to land
   on, so its press is the squeeze the drawing draws (scale .96 on 1e, .95 on
   1h) rather than the primary button's drop. */
.gs-choice__option:active:not([aria-disabled='true']) {
  transform: var(--gs-depth-styles-squeeze-transform);
  box-shadow: var(--gs-depth-flat);
}

/* The state colours, one custom property each, so a theme or a game restyles
   a state without restating its rule. Defaults are theme tokens.

   Selected is a light face with a strong outline, dark words and a check.
   Tom, 2026-09-27: the drawn state (2b), a stroke on the raised face, was
   hard to tell from idle on a phone, and a filled accent tile read as the
   primary action, or as "correct" before anybody had guessed. So selected is
   none of those colours: the ink and the surface swapped, which is the one
   pair every theme proves for contrast, plus a shape. Correct keeps the
   positive fill and wrong the negative stroke, so the three never share a
   colour.

   | Property                       | Default                     |
   | ---                            | ---                         |
   | --gs-choice-selected-fill      | --gs-color-ink              |
   | --gs-choice-selected-ink       | --gs-color-surface-solid    |
   | --gs-choice-selected-edge      | --gs-color-selected         |
   | --gs-choice-committed-fill     | selected fill, else --gs-color-interactive |
   | --gs-choice-committed-ink      | selected ink, else --gs-color-on-accent    |
   | --gs-choice-correct-fill       | --gs-color-positive         |
   | --gs-choice-correct-ink        | --gs-color-on-bright        |
   | --gs-choice-wrong-fill         | --gs-color-surface          |
   | --gs-choice-wrong-ink          | --gs-color-negative-solid   |
   | --gs-choice-wrong-edge         | --gs-color-negative-solid   |
   | --gs-choice-disabled-fill      | --gs-color-disabled         |
   | --gs-choice-disabled-ink       | --gs-color-disabled-ink     |
   | --gs-choice-unpicked-fill      | disabled fill, else --gs-color-disabled |
   | --gs-choice-unpicked-ink       | --gs-color-ink-secondary    | */
.gs-choice__option[data-gs-state='wrong'] {
  --gs-choice-grow: calc(var(--gs-stroke-selected) - var(--gs-stroke-control, var(--gs-stroke-hairline)));
}
/* The selected outline is a ring outside the option, drawn with a shadow,
   not a thicker border: a border takes its width from the label, and a 3px
   stroke cut "Tyrick Mitchell" to "Tyrick..." the moment it was picked. The
   ring changes nothing inside the option, so picking never re-fits a name. */
.gs-choice__option[data-gs-selected='true'] {
  background: var(--gs-choice-selected-fill, var(--gs-color-ink));
  color: var(--gs-choice-selected-ink, var(--gs-color-surface-solid));
  border-color: var(--gs-choice-selected-edge, var(--gs-color-selected));
  box-shadow: 0 0 0 var(--gs-stroke-selected) var(--gs-choice-selected-edge, var(--gs-color-selected)), var(--gs-depth-raised, none);
}
/* The check has its own slot on every option, selected or not, so a long name
   is fitted once and never runs under the mark. On a card the slot is the end
   of the detail line, which every card keeps, so the name has the full width;
   elsewhere the label gives up the corner's width. */
.gs-choice__option {
  padding-inline-end: calc(var(--gs-space-3) + 16px);
}
.gs-choice[data-gs-presentation='cards'] > .gs-choice__option {
  padding-inline-end: var(--gs-space-3);
}
.gs-choice[data-gs-presentation='cards'] .gs-choice__detail {
  padding-inline-end: 20px;
}
/* Drawn rather than a glyph from the set, so it needs no markup: a short and a
   long stroke in the selected ink. Gone once committed, where the padlock
   takes the corner. */
.gs-choice__option[data-gs-selected='true']:not([data-gs-committed='true'])::after {
  content: '';
  position: absolute;
  inset-block-start: 50%;
  inset-inline-end: var(--gs-space-3);
  inline-size: 7px;
  block-size: 13px;
  margin-block-start: -9px;
}
/* On a card, at the end of the reserved detail line. */
.gs-choice[data-gs-presentation='cards'] > .gs-choice__option[data-gs-selected='true']:not([data-gs-committed='true'])::after {
  inset-block-start: auto;
  inset-block-end: calc(var(--gs-space-3) + 4px);
  margin-block-start: 0;
}
.gs-choice__option[data-gs-selected='true']:not([data-gs-committed='true'])::after {
  border: solid var(--gs-choice-selected-ink, var(--gs-color-surface-solid));
  border-width: 0 3px 3px 0;
  transform: rotate(45deg);
  pointer-events: none;
}

/* Committed is drawn as a pressed primary: the interactive fill, the accent
   ink, the padlock, and the tile sitting down on its collapsed base (1h, 2b).
   The outline stays in edge, as every filled arcade face is. */
/* Committed follows selected when a game has restyled selected, and each
   pair comes from one level, never a fill from one and an ink from another:
   Stat Attack set a white selected card with purple words, and once a guess
   committed the card turned the theme's interactive teal while keeping a
   purple from the game, which nobody could read (Tom, 2026-09-27). A game
   that sets neither keeps the drawn committed face. */
.gs-choice__option[data-gs-committed='true'] {
  background: var(--gs-choice-committed-fill, var(--gs-choice-selected-fill, var(--gs-color-interactive)));
  color: var(--gs-choice-committed-ink, var(--gs-choice-selected-ink, var(--gs-color-on-accent)));
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-flat);
}

/* Result states change three things at once: fill or stroke, a glyph, and the
   text. A player who cannot see colour still gets the answer. */
.gs-choice__option[data-gs-state='correct'] {
  background: var(--gs-choice-correct-fill, var(--gs-color-positive));
  color: var(--gs-choice-correct-ink, var(--gs-color-on-bright));
}

/* Wrong: a dashed stroke at the selected width, the negative ink, the word
   struck through at the ui stroke. No shelf under it in any of the three
   drawings. */
.gs-choice__option[data-gs-state='wrong'] {
  background: var(--gs-choice-wrong-fill, var(--gs-color-surface));
  border-style: dashed;
  border-width: var(--gs-stroke-selected);
  border-color: var(--gs-choice-wrong-edge, var(--gs-color-negative-solid));
  color: var(--gs-choice-wrong-ink, var(--gs-color-negative-solid));
  box-shadow: var(--gs-depth-flat);
}
.gs-choice__option[data-gs-state='wrong'] .gs-choice__label {
  text-decoration: line-through;
  text-decoration-thickness: var(--gs-stroke-ui);
}

/* Arcade: the same fault the wrong plate had, light red on mid blue at
   2.6:1, and the same answer. The wrong option is filled in the negative
   with the dark bright ink, still struck through and still dashed, so it
   keeps its shape and its cross. Set on the theme as the defaults of the
   component's own properties, so a game that sets its own wrong paint on
   the choice or any container nearer it still wins. */
:where([data-gs-theme='arcade']) {
  --gs-choice-wrong-fill: var(--gs-color-negative);
  --gs-choice-wrong-ink: var(--gs-color-on-bright);
  --gs-choice-wrong-edge: var(--gs-color-edge);
}

/* A wrong answer shakes (specimen 4b: "motion.shake 400ms, ±6px, 3 cycles ·
   reduced-motion: dashed only"). The option already carries
   data-gs-animates="motion", so reduced motion zeroes this duration and the
   shake does not happen; the dashed stroke, the cross and the strikethrough are
   what is left, which is what the design asks for. The keyframe ends where it
   started and takes the default fill-mode, so an instant run leaves the option
   sitting exactly where it belongs. */
.gs-choice__option[data-gs-state='wrong'] {
  animation: gs-choice-shake var(--gs-motion-shake) var(--gs-motion-ease-shake);
}

@keyframes gs-choice-shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-6px); }
  40% { transform: translateX(6px); }
  60% { transform: translateX(-6px); }
  80% { transform: translateX(6px); }
}

/* Rewarded is a ring and a glow around the control, never a fill (BDS-012).
   `depth.reward` is both in one token: a gap ring in the background colour, the
   gold ring, then the glow.

   This used to fill the control with `color.reward` and switch the ink, which
   made it the same drawing as `correct` with a different hue. A reward then read
   as a second kind of right answer rather than as something won, and the fill
   also took the option's own colour away, which is what the design keeps: a
   normal control, ringed. The text is unchanged for the same reason BDS-012
   says so: the row already changes stroke and glyph, and a third change to the
   words would be the only result state that alters what it says. The outline
   stays in edge: 1e draws it gold in base and 2b draws it edge in arcade, and
   the control has one outline token. */
.gs-choice__option[data-gs-state='rewarded'] {
  box-shadow: var(--gs-depth-reward);
  /* The ring, the glow and the badge all extend past the control's own box, and
     the options are siblings in a grid, so without this the neighbour painted
     after it covers them. Lifting the option rather than the badge lifts all
     three together. */
  z-index: 1;
}

/* Outside the corner, not inside it: 12px up and 8px out, as 1e draws it.
   Inside, the amount is another line of text competing with the label;
   outside, it reads as something that arrived. The option is the positioned
   ancestor and `.gs-choice` sets no overflow, so nothing clips it. A figure,
   because it is a number in the display face. */
.gs-choice__reward {
  position: absolute;
  top: calc(-1 * var(--gs-space-3));
  right: calc(-1 * var(--gs-space-2));
  padding: var(--gs-space-1) var(--gs-space-2);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1;
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border-radius: var(--gs-radius-full);
  /* Emphasis, not motion: this duration survives reduced motion on purpose, and
     the badge is the only place the amount is drawn. */
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-choice__option[data-gs-locked='true'] { cursor: not-allowed; }

/* Locked keeps its shape and shows a padlock. Only disabled goes flat: the
   disabled fill, the disabled ink, and an outline that keeps the geometry
   without drawing (1e draws it transparent). */
.gs-choice__option[data-gs-disabled='true'] {
  background: var(--gs-choice-disabled-fill, var(--gs-color-disabled));
  color: var(--gs-choice-disabled-ink, var(--gs-color-disabled-ink));
  border-color: transparent;
  box-shadow: var(--gs-depth-flat);
  cursor: not-allowed;
}

/* Unpicked: the round is over and nobody picked this one (GSUI-295). It sat
   in the disabled drawing, whose ink measured 2.25 to 3.21:1 on its fill in
   every theme, which is right for a control nobody may press yet and wrong for
   an answer the player reads to see what else was on offer. It keeps the flat
   fill, so it still stands back from the answers that settled, and takes the
   secondary ink: 5.17:1 in base, 7.04 in arcade, 6.41 in stadium and 6.36 in
   paper. Its own properties, so a game can restyle it without touching
   disabled. */
.gs-choice__option[data-gs-unpicked='true'] {
  background: var(--gs-choice-unpicked-fill, var(--gs-choice-disabled-fill, var(--gs-color-disabled)));
  color: var(--gs-choice-unpicked-ink, var(--gs-color-ink-secondary));
}

.gs-choice__label  {
  font: inherit;
  /* The option is a flex column, so its label is a flex item and stops
     shrinking at its longest word. A driver's name is one word. */
  min-inline-size: 0;
  max-inline-size: 100%;

  /* Label fit, GSUI-281. The label fills its option's width, because that is
     the box it is fitted to; as a flex item it would otherwise be only as wide
     as its own text and every label would appear to fit. The group decides the
     size (--gs-label-scale) and the line count (--gs-label-lines) once it has
     measured; past the line count the text ends in an ellipsis. Under
     `uniform`, --gs-label-block reserves that many lines on every label, so
     every option in a group is the same height.

     The text is centred in that reserved block, not pinned to its top. A
     one-line label used to sit a whole line above centre: Verstappen was 5px
     from the top of its chip and 16px from the bottom. Tom, 2026-09-28. */
  align-self: stretch;
  /* Its width comes from the option, never its text: a long name once widened
     its card past the phone (517px at 390). */
  contain: inline-size;
  font-size: calc(1em * var(--gs-label-scale, 1));
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-block-size: calc(var(--gs-label-block, 0) * 1lh);
}
/* The clamp lives on the text, because a -webkit-box cannot centre itself in a
   taller box. */
.gs-choice__text {
  min-inline-size: 0;
  /* A word is never broken in half (GSUI-235). This was
     `overflow-wrap: anywhere`, and in the `cards` presentation at 390 it drew
     the demo's first answer as "Verstap / pen": the card is a 148px column,
     the label's content box 110, and "Verstappen" a 149px run. The buttons
     grid escapes that only because the container query above drops it to one
     column first, and cards is auto-fit with no such rule behind it.

     `normal` keeps the break between words and cuts a word that cannot fit
     with an ellipsis. The text itself is untouched, so the option's accessible
     name still carries the whole word. Half a name with nothing to say it is
     half is an answer to be guessed at; "Versta…" says there is more. */
  overflow-wrap: normal;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--gs-label-lines, 2);
  line-clamp: var(--gs-label-lines, 2);
}
/* One line, cut with an ellipsis. */
.gs-choice[data-gs-label-fit='truncate'] .gs-choice__text {
  display: block;
  white-space: nowrap;
}
.gs-choice__detail {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
  text-transform: none;
}

/* The key in the tile's corner, specimen 1h: A, B, C, D on a raised square in
   the display face, and the place the tick or the cross lands once the option
   settles. The drawing draws it at 28px with 9px corners; the nearest tokens
   are the 24px control icon and the 12px small radius, and design/twins/1h
   carries both gaps as a token request. */
.gs-choice__key {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-sm);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1;
  color: inherit;
  background: var(--gs-color-surface-raised);
  /* Emphasis, not motion: the key's fill is how a colour-blind player reads the
     result, so it survives reduced motion. */
  transition: background-color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* Under the interactive fill the key is a lighter square of the same ink. */
.gs-choice__option[data-gs-committed='true'] .gs-choice__key {
  background: color-mix(in oklch, currentColor 25%, transparent);
}

/* The tick sits on a bright disc in the positive ink; the cross on a negative
   disc in the accent ink. Fill and glyph together, so neither is the only
   signal. */
.gs-choice__option[data-gs-state='correct'] .gs-choice__key {
  background: var(--gs-color-on-bright);
  color: var(--gs-color-positive-solid);
}
.gs-choice__option[data-gs-state='wrong'] .gs-choice__key {
  background: var(--gs-color-negative-solid);
  color: var(--gs-color-on-accent);
}

/* An option carrying a mark in its corner has to stop its text short of it.
   The mark is absolutely positioned so that arriving at settlement does not
   reflow the label, which means the label does not know it is there and a long
   one runs underneath: measured on the lab, "Verstappen" overlapped the tick by
   15px.

   It was always this way and the text glyphs hid it, because a character inks
   about seven tenths of its em box and leaves the rest as sidebearing, while a
   drawn mark fills the box it is given. Reserving the mark's own size plus the
   offset it sits at is the fix either way. :has rather than a state selector, so
   this cannot drift out of step with which states carry a mark. A mark inside
   the key takes no corner, so only a direct child counts. */
.gs-choice__option:has(> .gs-choice__glyph) {
  padding-inline-end: calc(var(--gs-size-icon-control) + var(--gs-space-2) * 2);
}

.gs-choice__glyph {
  position: absolute;
  top: var(--gs-space-2);
  right: var(--gs-space-2);
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* Inside the key the mark is the key's own size and sits where the letter did. */
.gs-choice__key .gs-choice__glyph {
  position: static;
  display: inline-flex;
  font-size: inherit;
}

/* Where the commit control goes, whoever renders it: across the grid, under
   the options. This is the only rule a host's own control inherits, because
   placement is Choice's business and paint is not. */
.gs-choice__commit {
  grid-column: 1 / -1;
}

/* What Choice's own control looks like. A host that takes the control over
   brings its own face, usually the library's Button, and two sets of paint on
   one element is how a control ends up with two backgrounds and two shelves. */
.gs-choice__commit--default {
  min-height: var(--gs-size-action);
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  box-shadow: var(--gs-depth-pressable);
  cursor: pointer;
  transition: transform var(--gs-motion-press) var(--gs-motion-ease-press), box-shadow var(--gs-motion-press) var(--gs-motion-ease-press);
}

/* The offset base collapses and the control travels down by the same amount, so
   the face lands where the base was. */
.gs-choice__commit--default:active { transform: var(--gs-press-transform); box-shadow: var(--gs-depth-pressable-pressed); }
.gs-choice__commit--default:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-color-ink); outline-offset: 3px; }

/* A person's name on two lines: the given name small and light, the family
   name large and bold, both centred, in every state. The given line keeps the
   14px floor. Tom, 2026-09-28. */
.gs-choice__label[data-gs-names] {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  line-height: 1.1;
}

.gs-choice__given {
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-body-font-weight);
  opacity: 0.85;
}

.gs-choice__family {
  font-weight: var(--gs-type-title-font-weight);
}
